import axios from "axios";

const API = axios.create({ baseURL: "http://localhost:3001" }); // Replace with your backend URL

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = localStorage.getItem("token"); // Get the token from localStorage
    if (token) {
        req.headers.Authorization = `Bearer ${token}`;
    }
    return req;
});

// Handle response errors globally
API.interceptors.response.use(
    response => response, // If the response is okay, just return it
    error => {
        // Check for token expiry or invalid token
        if (error.response && error.response.status === 401) {
            // Handle unauthorized error (token expired or invalid)
            localStorage.removeItem("token"); // Remove invalid token
            // You can redirect the user to the login page or show a message
            alert("Session expired. Please log in again.");
        }
        return Promise.reject(error); // Forward the error to be handled by the calling code
    }
);

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        const response = await API.post('/api/login', { username, password });
        // Save the token to localStorage after login
        if (response.data.token) {
            localStorage.setItem("token", response.data.token);
        }
        return response.data; // Assuming response structure: { data: { token, user }}
    } catch (error) {
        console.error("Login failed:", error);
        throw error; // Rethrow the error so you can handle it in the component
    }
};

// Franchise APIs
export const createFranchise = async (data) => {
    try {
        const response = await API.post("/franchises", data);
        return response.data;
    } catch (error) {
        console.error("Error creating franchise:", error);
        throw error;
    }
};

export const getFranchises = async () => {
    try {
        const response = await API.get("/dashboard");
        return response.data;
    } catch (error) {
        console.error("Error fetching franchises:", error);
        throw error;
    }
};

export const deleteFranchise = async (id) => {
    try {
        const response = await API.delete(`/franchises/${id}`);
        return response.data;
    } catch (error) {
        console.error("Error deleting franchise:", error);
        throw error;
    }
};

export const updateFranchise = async (id, data) => {
    try {
        const response = await API.put(`/franchises/${id}`, data);
        return response.data;
    } catch (error) {
        console.error("Error updating franchise:", error);
        throw error;
    }
};

// User APIs
export const createUser = async (data) => {
    try {
        const response = await API.post("/users", data); // Pass the data containing franchiseId
        return response.data;
    } catch (error) {
        console.error("Error creating user:", error);
        throw error;
    }
};

// Function to get users
export const getUsers = async () => {
    try {
        const response = await API.get("/users");
        return response.data;
    } catch (error) {
        console.error("Error fetching users:", error);
        throw error;
    }
};

// Function to delete a user by ID
export const deleteUser = async (userId) => {
    try {
        const response = await API.delete(`/users/${userId}`);
        return response.data;
    } catch (error) {
        console.error("Error deleting user:", error);
        throw error;
    }
};

// Function to update a user by ID
export const updateUser = async (userId, userData) => {
    try {
        const response = await API.put(`/users/${userId}`, userData);
        return response.data;
    } catch (error) {
        console.error("Error updating user:", error);
        throw error;
    }
};

// Update Exam Data APIs for a franchise
export const updateExamData = async (franchiseId, data) => {
    try {
        const response = await API.put(`/franchises/${franchiseId}/exam-data`, data);
        return response.data;
    } catch (error) {
        console.error("Error updating exam data:", error);
        throw error;
    }
};
